<?php
require_once __DIR__.'/_init.php';
$filter=trim($_GET['type']??'');$types=$pdo->query('SELECT DISTINCT activity_type FROM ds_activity_logs ORDER BY activity_type')->fetchAll(PDO::FETCH_COLUMN);
$sql='SELECT l.*,a.name admin_name FROM ds_activity_logs l LEFT JOIN ds_admins a ON a.id=l.admin_id';$params=[];if($filter!==''){$sql.=' WHERE l.activity_type=?';$params[]=$filter;}$sql.=' ORDER BY l.id DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
admin_header('Monitoring Aktivitas','activities');?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">ACTIVITY MONITORING</span><h2>Riwayat aktivitas website</h2><p class="muted">Mencatat kunjungan halaman, pencarian, kategori, komentar, pesan kontak, dan tindakan admin.</p></div><form method="get"><select name="type" onchange="this.form.submit()"><option value="">Semua aktivitas</option><?php foreach($types as $t):?><option value="<?=e($t)?>" <?=$filter===$t?'selected':''?>><?=e(str_replace('_',' ',$t))?></option><?php endforeach;?></select></form></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Waktu</th><th>Aktivitas</th><th>Deskripsi</th><th>Pelaku</th><th>IP</th><th>Perangkat / Browser</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d/m/Y H:i:s',strtotime($r['created_at'])))?></td><td><span class="activity-pill"><?=e(str_replace('_',' ',$r['activity_type']))?></span></td><td><?=e($r['description'])?></td><td><?=e($r['admin_name']??'Pengunjung')?></td><td><?=e($r['ip_address']??'-')?></td><td class="message-cell"><?=e($r['user_agent']??'-')?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Menampilkan maksimal 300 aktivitas terbaru. Alamat IP hanya untuk kebutuhan keamanan dan audit dasar.</p></div><?php admin_footer();?>
